def backfill_api_key_hashes(apps, schema_editor):
    """Hash existing plaintext API keys so lookups no longer need the plaintext column."""
    import hashlib
    APIKey = apps.get_model('agents', 'APIKey')
    for key in APIKey.objects.filter(key_hash__isnull=True).exclude(key__isnull=True).exclude(key=''):
        key.key_hash = hashlib.sha256(key.key.encode('utf-8')).hexdigest()
        key.key_prefix = key.key[:8]
        key.save(update_fields=['key_hash', 'key_prefix'])


